import type { Request, Response } from 'express';

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  image: string;
  description: string;
  featured?: boolean;
}

const products: Product[] = [
  // Pottery
  {
    id: 'p1',
    name: 'Terracotta Serving Bowl',
    category: 'pottery',
    price: 68,
    image: '/airo-assets/images/products/pottery-hero',
    description: 'Hand-thrown on the wheel from local red clay, this generous serving bowl is finished with a warm matte glaze.',
    featured: true,
  },
  {
    id: 'p2',
    name: 'Speckled Mug Set',
    category: 'pottery',
    price: 54,
    image: '/airo-assets/images/products/pottery-hero',
    description: 'A set of two wheel-thrown mugs with a speckled ash glaze. Each piece is unique.',
  },
  {
    id: 'p3',
    name: 'Sage Bud Vase',
    category: 'pottery',
    price: 38,
    image: '/airo-assets/images/products/pottery-hero',
    description: 'A slender bud vase in a soft sage glaze, perfect for a single stem or small wildflower bouquet.',
  },
  // Textiles
  {
    id: 't1',
    name: 'Linen Throw Blanket',
    category: 'textiles',
    price: 124,
    image: '/airo-assets/images/products/textiles-hero',
    description: 'Hand-loomed from 100% natural linen, this lightweight throw adds warmth and texture to any space.',
    featured: true,
  },
  {
    id: 't2',
    name: 'Woven Table Runner',
    category: 'textiles',
    price: 58,
    image: '/airo-assets/images/products/textiles-hero',
    description: 'A hand-woven table runner in natural cotton and linen blend with subtle stripe detail.',
  },
  {
    id: 't3',
    name: 'Indigo Dyed Napkins',
    category: 'textiles',
    price: 42,
    image: '/airo-assets/images/products/textiles-hero',
    description: 'Set of four napkins naturally dyed with indigo. Each piece carries its own unique variation.',
  },
  // Woodwork
  {
    id: 'w1',
    name: 'Walnut Serving Board',
    category: 'woodwork',
    price: 96,
    image: '/airo-assets/images/products/woodwork-hero',
    description: 'Hand-carved from a single piece of black walnut, this serving board is finished with food-safe oil.',
    featured: true,
  },
  {
    id: 'w2',
    name: 'Oak Salad Bowl',
    category: 'woodwork',
    price: 112,
    image: '/airo-assets/images/products/woodwork-hero',
    description: 'Turned on the lathe from solid white oak, this salad bowl has a smooth, tactile finish.',
  },
  {
    id: 'w3',
    name: 'Cedar Candle Holder',
    category: 'woodwork',
    price: 34,
    image: '/airo-assets/images/products/woodwork-hero',
    description: 'A simple, elegant candle holder turned from aromatic cedar. Fits standard taper candles.',
  },
  // Jewelry
  {
    id: 'j1',
    name: 'River Stone Pendant',
    category: 'jewelry',
    price: 78,
    image: '/airo-assets/images/products/jewelry-hero',
    description: 'A smooth river stone wrapped in sterling silver wire, hung on a delicate 18" chain.',
    featured: true,
  },
  {
    id: 'j2',
    name: 'Hammered Brass Cuffs',
    category: 'jewelry',
    price: 62,
    image: '/airo-assets/images/products/jewelry-hero',
    description: 'Hand-hammered brass cuffs with a warm, antiqued finish. Sold as a pair.',
  },
  {
    id: 'j3',
    name: 'Ceramic Bead Necklace',
    category: 'jewelry',
    price: 88,
    image: '/airo-assets/images/products/jewelry-hero',
    description: 'Hand-rolled ceramic beads in earthy tones, strung on waxed linen cord with a brass clasp.',
  },
];

export default function handler(req: Request, res: Response) {
  const { category } = req.query;

  let filtered = products;
  if (category && category !== 'all') {
    filtered = products.filter((p) => p.category === category);
  }

  res.json(filtered);
}

