          {product.name}
        </h3>
        <p className="text-muted-foreground text-sm mt-1 line-clamp-2">{product.description}</p>
        <p className="text-foreground font-medium mt-2">${product.price}</p>
      </div>
    </motion.article>
  );
}

export default function ProductsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const initialCategory = (searchParams.get('category') as Category) || 'all';
  const [activeCategory, setActiveCategory] = useState<Category>(initialCategory);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const cat = (searchParams.get('category') as Category) || 'all';
    setActiveCategory(cat);
  }, [searchParams]);

  useEffect(() => {
    setLoading(true);
    const url = activeCategory === 'all' ? '/api/products' : `/api/products?category=${activeCategory}`;
    fetch(url)
      .then((r) => r.json())
      .then((data: Product[]) => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [activeCategory]);

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    if (cat === 'all') {
      setSearchParams({});
    } else {
      setSearchParams({ category: cat });
    }
  };

  const categoryLabel = CATEGORIES.find((c) => c.value === activeCategory)?.label ?? 'All';

  return (
    <>
      <Helmet>
        <title>{categoryLabel} — Shop Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse our full collection of handcrafted pottery, textiles, woodwork, and jewelry. Each piece is made by skilled artisans."
        />
      </Helmet>

      {/* Page Header */}
      <section className="py-16 px-6 lg:px-8 border-b border-border/60 bg-muted/40">
        <div className="container mx-auto">
          <div className="flex items-center gap-2 text-xs text-muted-foreground mb-4">
            <Link to="/" className="hover:text-primary transition-colors">Home</Link>
            <span>/</span>
            <span>Shop</span>
          </div>
          <h1 className="font-heading text-4xl md:text-5xl text-foreground">The Collection</h1>
          <p className="text-muted-foreground mt-3 max-w-xl">
            Every piece is made by hand, with care. Browse by category or explore the full collection.
          </p>
        </div>
      </section>

      {/* Filters + Grid */}
      <section className="py-12 px-6 lg:px-8">
        <div className="container mx-auto">
          {/* Category Filters */}
          <div className="flex flex-wrap gap-2 mb-12" role="tablist" aria-label="Filter by category">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.value}
                role="tab"
                aria-selected={activeCategory === cat.value}
                onClick={() => handleCategoryChange(cat.value)}
                className={`px-5 py-2 text-sm font-medium rounded-sm border transition-all duration-200 ${
                  activeCategory === cat.value
                    ? 'bg-primary text-primary-foreground border-primary'
                    : 'bg-background text-foreground/60 border-border hover:border-primary/50 hover:text-foreground'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>

          {/* Product Grid */}
          {loading ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {[...Array(6)].map((_, i) => <ProductSkeleton key={i} />)}
            </div>
          ) : products.length === 0 ? (
            <div className="text-center py-24 text-muted-foreground">
              <p className="font-heading text-2xl mb-2">No products found</p>
              <p className="text-sm">Try a different category.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {products.map((product, i) => (
                <ProductCard key={product.id} product={product} index={i} />
              ))}
            </div>
          )}
        </div>
      </section>
    </>
  );
}

