/** Return all products, optionally filtered by category. */
export function getProducts(category?: ProductCategory | 'all'): Product[] {
  if (!category || category === 'all') return ALL_PRODUCTS;
  return ALL_PRODUCTS.filter((p) => p.category === category);
}

/** Return only featured products, up to an optional limit. */
export function getFeaturedProducts(limit?: number): Product[] {
  const featured = ALL_PRODUCTS.filter((p) => p.featured);
  return limit ? featured.slice(0, limit) : featured;
}

/** Look up a single product by id. Returns undefined if not found. */
export function getProductById(id: string): Product | undefined {
  return ALL_PRODUCTS.find((p) => p.id === id);
}

import type { Request, Response } from 'express';
import { getProducts } from '../../../lib/products-data.js';
import type { ProductCategory } from '../../../lib/products-data.js';

export default function handler(req: Request, res: Response) {
  const { category } = req.query;
  const filtered = getProducts(category as ProductCategory | 'all' | undefined);
  res.json(filtered);
}

